import React, { useEffect, useState } from "react";
import { User } from "firebase/auth";
import { getDatabase, ref, get } from "firebase/database";

interface PerfilProps {
  user: User;
}

const Perfil: React.FC<PerfilProps> = ({ user }) => {
  const [fotoPerfil, setFotoPerfil] = useState<string>(
    "https://i.pravatar.cc/150?img=3"
  );
  const gruposBotones = [
    ["Lunes", "Martes"],
    ["Miércoles", "Jueves"],
    ["Viernes", "Sábado"],
    ["Domingo", "Extra"],
  ];

  useEffect(() => {
    const db = getDatabase();
    const fotoRef = ref(db, `usuarios/${user.uid}/avatar`);
    get(fotoRef).then((snapshot) => {
      if (snapshot.exists()) setFotoPerfil(snapshot.val());
    });
  }, [user.uid]);

  return (
    <div className="min-h-screen bg-gray-50 p-6 flex gap-6">
      {/* Contenido principal */}
      <div className="flex-1 max-w-4xl mx-auto">
        <h1 className="text-3xl font-bold text-gray-800 mb-6">
          Horarios de la Semana
        </h1>

        {/* Tabla de años */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">
            Horarios jugados este mes
          </h2>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50">
                <tr>
                  <th className="p-3 text-left text-sm font-medium text-gray-700"></th>
                  {[
                    2016, 2017, 2018, 2020, 2021, 2022, 2023, 2024, 2025, 2026,
                    2027, 2028,
                  ].map((year) => (
                    <th
                      key={year}
                      className="p-3 text-center text-sm font-medium text-gray-700"
                    >
                      {year}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td className="p-3 text-sm font-medium text-gray-900 border-t border-gray-200">
                    Deep Feeder
                  </td>
                  {[...Array(12)].map((_, i) => (
                    <td
                      key={i}
                      className="p-3 text-center text-sm text-gray-600 border-t border-gray-200"
                    >
                      -
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        {/* Perfil */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <div className="flex items-center gap-4">
            <img
              src={fotoPerfil}
              alt="Avatar"
              className="w-16 h-16 rounded-full border-2 border-blue-500"
            />
            <div>
              <h3 className="text-lg font-semibold text-gray-900">
                {user.displayName}
              </h3>
              <p className="text-sm text-gray-600">{user.email}</p>
              <p className="text-sm text-gray-500 mt-1">
                Miembro desde:{" "}
                {new Date(user.metadata.creationTime!).toLocaleDateString()}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Barra lateral de botones */}
      <div className="w-72">
        <div className="bg-white rounded-lg shadow-md p-4 sticky top-6">
          <div className="space-y-4">
            {gruposBotones.map((par, index) => (
              <div key={index} className="space-y-2">
                {par.map((dia) => (
                  <button
                    key={dia}
                    className="w-full px-4 py-2 bg-blue-600 text-white text-sm rounded-md 
                             hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 
                             transition-colors"
                  >
                    Horarios {dia}
                  </button>
                ))}
                {index < gruposBotones.length - 1 && (
                  <div className="border-b border-gray-200 my-2" />
                )}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Perfil;
